mapper.select:
SELECT g.*, p.plot_name as plotName FROM gateway g LEFT JOIN plot p ON g.plot_id = p.id WHERE g.deleted = 0
AND g.gateway_code LIKE CONCAT('%', #{dto.gatewayCode}, '%')
AND g.gateway_name LIKE CONCAT('%', #{dto.gatewayName}, '%')
AND g.plot_id = #{dto.plotId}
AND g.online_status = #{dto.onlineStatus}
ORDER BY g.create_time DESC
